package gitrepo

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

// ErrWorktreeMetadataNotFound reports that an explicit worktree root has no
// .git entry. Repository opening uses this to distinguish a possible bare
// repository from malformed metadata in a checkout.
var ErrWorktreeMetadataNotFound = errors.New("worktree Git metadata not found")

// WorktreeMetadata contains Git directory facts for one explicit worktree
// root. Paths are cleaned and absolute but retain their lexical spelling;
// WorktreeID uses physical directory identity internally.
type WorktreeMetadata struct {
	GitDir     string
	CommonDir  string
	WorktreeID string
}

// ResolveWorktreeMetadata resolves filesystem metadata for an explicit
// worktree root. It does not discover a root, inspect Git environment
// variables, run Git, cache results, or decide feature-specific policy.
func ResolveWorktreeMetadata(worktreeRoot string) (WorktreeMetadata, error) {
	if strings.TrimSpace(worktreeRoot) == "" {
		return WorktreeMetadata{}, errors.New("worktree root is required")
	}

	root, err := filepath.Abs(worktreeRoot)
	if err != nil {
		return WorktreeMetadata{}, fmt.Errorf("resolve worktree root %q: %w", worktreeRoot, err)
	}
	root = filepath.Clean(root)

	gitDir, err := resolveWorktreeGitDir(root)
	if err != nil {
		return WorktreeMetadata{}, err
	}
	commonDir, err := resolveWorktreeCommonDir(gitDir)
	if err != nil {
		return WorktreeMetadata{}, err
	}
	worktreeID, err := resolveWorktreeID(gitDir, commonDir)
	if err != nil {
		return WorktreeMetadata{}, err
	}

	return WorktreeMetadata{
		GitDir:     gitDir,
		CommonDir:  commonDir,
		WorktreeID: worktreeID,
	}, nil
}

func resolveWorktreeGitDir(worktreeRoot string) (string, error) {
	gitEntry := filepath.Join(worktreeRoot, gitDir)
	info, err := os.Lstat(gitEntry)
	if errors.Is(err, fs.ErrNotExist) {
		return "", fmt.Errorf("%w at %s: %w", ErrWorktreeMetadataNotFound, gitEntry, err)
	}
	if err != nil {
		return "", fmt.Errorf("inspect .git entry at %s: %w", gitEntry, err)
	}
	if info.Mode()&fs.ModeSymlink != 0 {
		info, err = os.Stat(gitEntry)
		if err != nil {
			return "", fmt.Errorf("inspect .git entry at %s: %w", gitEntry, err)
		}
	}
	if info.IsDir() {
		return gitEntry, nil
	}
	if !info.Mode().IsRegular() {
		return "", fmt.Errorf(".git entry at %s is neither a directory nor a regular file", gitEntry)
	}

	content, err := os.ReadFile(gitEntry) //nolint:gosec // path is anchored at the explicit worktree root.
	if err != nil {
		return "", fmt.Errorf("read .git file at %s: %w", gitEntry, err)
	}
	pointer, ok := strings.CutPrefix(strings.TrimRight(string(content), "\r\n"), "gitdir: ")
	if !ok {
		return "", fmt.Errorf("parse .git file at %s: missing gitdir prefix", gitEntry)
	}
	if pointer == "" {
		return "", fmt.Errorf("parse .git file at %s: empty gitdir value", gitEntry)
	}

	resolved := resolveMetadataPath(worktreeRoot, pointer)
	if err := requireDirectory("Git directory", resolved); err != nil {
		return "", err
	}
	return filepath.Clean(resolved), nil
}

func resolveWorktreeCommonDir(gitDirPath string) (string, error) {
	commonFile := filepath.Join(gitDirPath, "commondir")
	info, err := os.Lstat(commonFile)
	if errors.Is(err, fs.ErrNotExist) {
		return gitDirPath, nil
	}
	if err != nil {
		return "", fmt.Errorf("inspect commondir file at %s: %w", commonFile, err)
	}
	if !info.Mode().IsRegular() {
		return "", fmt.Errorf("commondir entry at %s is not a regular file", commonFile)
	}

	content, err := os.ReadFile(commonFile) //nolint:gosec // path is inside the validated per-worktree Git directory.
	if err != nil {
		return "", fmt.Errorf("read commondir file at %s: %w", commonFile, err)
	}
	pointer := strings.TrimRight(string(content), "\r\n")
	if pointer == "" {
		return "", fmt.Errorf("parse commondir file at %s: empty value", commonFile)
	}

	resolved := resolveMetadataPath(gitDirPath, pointer)
	if err := requireDirectory("common Git directory", resolved); err != nil {
		return "", err
	}
	return filepath.Clean(resolved), nil
}

func resolveWorktreeID(gitDirPath, commonDir string) (string, error) {
	same, err := directoriesIdentifySameFile(gitDirPath, commonDir)
	if err != nil {
		return "", fmt.Errorf("compare Git and common directories: %w", err)
	}
	if same {
		return "", nil
	}

	registrationRoot := filepath.Join(commonDir, "worktrees")
	same, err = directoriesIdentifySameFile(filepath.Dir(gitDirPath), registrationRoot)
	if err != nil {
		return "", fmt.Errorf("validate linked-worktree registration for %s: %w", gitDirPath, err)
	}
	if !same {
		return "", fmt.Errorf("git directory %s is not an immediate child of %s", gitDirPath, registrationRoot)
	}

	id := filepath.Base(gitDirPath)
	if id == "." || id == string(filepath.Separator) || id == "" {
		return "", fmt.Errorf("git directory %s has no worktree registration name", gitDirPath)
	}
	return id, nil
}

// Keep every component until after validation so malformed paths cannot use
// lexical cleaning to bypass a missing intermediate directory.
func resolveMetadataPath(base, value string) string {
	if filepath.IsAbs(value) {
		return value
	}
	return base + string(filepath.Separator) + value
}

func requireDirectory(label, path string) error {
	info, err := os.Stat(path) //nolint:gosec // the explicit-root API intentionally resolves caller-selected repository metadata.
	if err != nil {
		return fmt.Errorf("inspect %s at %s: %w", label, path, err)
	}
	if !info.IsDir() {
		return fmt.Errorf("%s at %s is not a directory", label, path)
	}
	return nil
}

func directoriesIdentifySameFile(a, b string) (bool, error) {
	aInfo, err := os.Stat(a)
	if err != nil {
		return false, fmt.Errorf("inspect %s: %w", a, err)
	}
	if !aInfo.IsDir() {
		return false, fmt.Errorf("%s is not a directory", a)
	}
	bInfo, err := os.Stat(b)
	if err != nil {
		return false, fmt.Errorf("inspect %s: %w", b, err)
	}
	if !bInfo.IsDir() {
		return false, fmt.Errorf("%s is not a directory", b)
	}
	return os.SameFile(aInfo, bInfo), nil
}
package gitrepo

import (
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"testing"
)

func TestGitMetadataTraversalHasSingleOwner(t *testing.T) {
	t.Parallel()
	allowedDotGitInspections := map[string]string{
		"agent/codex/hook_root.go:hasDotGitEntry": "Codex policy checks whether a candidate checkout owns a .git entry",
		"plugin_index.go:SyncPluginIndex":         "the plugin cache checks whether its private clone has been materialized",
	}

	_, thisFile, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("resolve guard source path")
	}
	cliRoot := filepath.Dir(filepath.Dir(thisFile))
	fset := token.NewFileSet()
	ownerTokens := 0
	allowedSeen := map[string]bool{}

	err := filepath.WalkDir(cliRoot, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(cliRoot, path)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		if !strings.HasSuffix(rel, ".go") || strings.HasSuffix(rel, "_test.go") ||
			strings.HasPrefix(rel, "integration_test/") || strings.HasPrefix(rel, "benchutil/") {
			return nil
		}

		file, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return err
		}
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Body == nil {
				continue
			}
			ast.Inspect(fn.Body, func(node ast.Node) bool {
				switch n := node.(type) {
				case *ast.BasicLit:
					if n.Kind != token.STRING {
						return true
					}
					value, unquoteErr := strconv.Unquote(n.Value)
					if unquoteErr != nil {
						return true
					}
					if strings.HasPrefix(rel, "gitrepo/") {
						if strings.Contains(value, "gitdir:") || value == "commondir" {
							ownerTokens++
						}
						return true
					}
					if strings.Contains(value, "gitdir:") || value == "commondir" {
						t.Errorf("%s independently parses Git metadata token %q; use gitrepo.ResolveWorktreeMetadata", fset.Position(n.Pos()), value)
					}
				case *ast.CallExpr:
					if strings.HasPrefix(rel, "gitrepo/") || !isOSMetadataInspection(n) || !containsStringLiteral(n, ".git") {
						return true
					}
					key := rel + ":" + fn.Name.Name
					if _, allowed := allowedDotGitInspections[key]; allowed {
						allowedSeen[key] = true
						return true
					}
					t.Errorf("%s independently inspects a .git entry; use gitrepo.ResolveWorktreeMetadata or document a narrow policy exception", fset.Position(n.Pos()))
				}
				return true
			})
		}
		return nil
	})
	if err != nil {
		t.Fatalf("scan Go sources: %v", err)
	}
	if ownerTokens == 0 {
		t.Fatal("guard found no canonical gitdir/commondir parser tokens; update the guard with the metadata owner")
	}
	for key, reason := range allowedDotGitInspections {
		if !allowedSeen[key] {
			t.Errorf("documented .git inspection exception %s (%s) no longer exists; remove or update the exception", key, reason)
		}
	}
}

func isOSMetadataInspection(call *ast.CallExpr) bool {
	selector, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	pkg, ok := selector.X.(*ast.Ident)
	if !ok || pkg.Name != "os" {
		return false
	}
	switch selector.Sel.Name {
	case "Lstat", "Open", "OpenFile", "ReadDir", "ReadFile", "Stat":
		return true
	default:
		return false
	}
}

func containsStringLiteral(node ast.Node, want string) bool {
	found := false
	ast.Inspect(node, func(n ast.Node) bool {
		literal, ok := n.(*ast.BasicLit)
		if !ok || literal.Kind != token.STRING {
			return true
		}
		value, err := strconv.Unquote(literal.Value)
		if err == nil && value == want {
			found = true
			return false
		}
		return true
	})
	return found
}
// Package gitdir owns access to the git common directory — .git in an ordinary
// checkout, and the main repository's .git when running from a linked worktree.
//
// Entire keeps a lot of state there, deliberately: session state, advisory
// locks, the checkpoint push queue, the redaction prefix cache, investigation
// runs, review manifests, and the captured checkpoint-sync election all live in
// the common dir rather than under .entire, because they are per-clone and must
// not be committed or walked into a checkpoint tree. That makes this directory
// the same kind of trust surface .entire is, and it gets the same treatment: one
// *os.Root per common dir, opened once and shared, with every read and write
// resolved as a name inside it.
//
// Two properties come from that, and neither survives a call site reverting to
// os.ReadFile on a joined path:
//
//   - Containment. Names here are built from agent-supplied session IDs and
//     investigation run IDs. Several call sites carry hand-written comments
//     explaining that an unvalidated ID would be a path-traversal sink feeding
//     os.RemoveAll. A root makes that structural instead of a precondition each
//     caller has to keep honouring.
//   - One directory handle per clone. gitrepo owns physical metadata
//     resolution; this package owns confined access to the resolved directory.
//
// Unlike .entire there is no create/no-create split: the common dir is the
// repository, so it always exists by the time anything here is called. What
// needs creating are Entire's own subdirectories inside it, via
// osroot.MkdirAllNoSymlink.
package gitdir

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// CommonDir returns the absolute common Git directory for the current
// worktree. Root discovery remains context-aware; physical metadata traversal
// is context-free and uncached.
func CommonDir(ctx context.Context) (string, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return "", fmt.Errorf("resolve worktree root: %w", err)
	}
	metadata, err := gitrepo.ResolveWorktreeMetadata(worktreeRoot)
	if err != nil {
		return "", fmt.Errorf("resolve worktree metadata: %w", err)
	}
	return metadata.CommonDir, nil
}

// Open returns the shared *os.Root over the git common directory. The returned
// root is owned by this package and shared with every other caller; do not
// close it.
func Open(ctx context.Context) (*os.Root, error) {
	dir, err := CommonDir(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAt(dir)
}

// OpenAt is Open for an explicit git directory — the common dir for callers that
// already resolved one or that act on another clone, and the per-worktree git
// dir for the few things that genuinely live there rather than in the common dir
// (the rebase/cherry-pick sequence markers).
func OpenAt(commonDir string) (*os.Root, error) {
	if commonDir == "" {
		return nil, errors.New("gitdir: common dir is required")
	}
	abs, err := filepath.Abs(commonDir)
	if err != nil {
		return nil, fmt.Errorf("resolve %s: %w", commonDir, err)
	}

	// osroot.Shared owns the open-at-most-once registry, shared with the other
	// anchors, and returns a missing directory unwrapped so callers can classify
	// it with os.IsNotExist — an ordinary outcome for a store asked about a repo
	// that has none.
	return osroot.Shared(abs) //nolint:wrapcheck // see comment
}

// Reset closes and forgets every cached root, and the resolved path with them.
// Call it after deleting or replacing a common dir: a root that outlives its
// directory is a handle to an unlinked inode, so writes through it succeed and
// land nowhere. The root registry is shared with the other anchors, so this
// clears those too.
func Reset() {
	osroot.ResetShared()
}

// CommonDirForWorktree returns the absolute git common directory for the
// repository at worktreeRoot, independent of the process's working directory.
//
// Callers acting on a repo passed as an argument (agent import, session adopt)
// must use this rather than CommonDir: the cwd-resolved form answers for
// whatever repo the process happens to be running in, which is how test
// fixtures once leaked session state into a developer's real
// .git/entire-sessions and hijacked commit linking.
//
// Not cached: the per-cwd cache CommonDir keeps would be wrong here, since the
// answer varies with the argument rather than with the process.
func CommonDirForWorktree(_ context.Context, worktreeRoot string) (string, error) {
	// An empty root would silently degrade to the process cwd (cmd.Dir = ""),
	// reproducing exactly the accidental-repo leak this exists to prevent.
	if worktreeRoot == "" {
		return "", errors.New("gitdir: worktree root required to resolve a git common dir")
	}
	metadata, err := gitrepo.ResolveWorktreeMetadata(worktreeRoot)
	if err != nil {
		return "", fmt.Errorf("resolve git common dir for %s: %w", worktreeRoot, err)
	}
	return metadata.CommonDir, nil
}

// OpenPathIn returns the shared root for commonDir together with absPath's name
// inside it, so a consumer holding an absolute path it was handed earlier can
// still read through the one root rather than through the path.
//
// It refuses a path that is not under commonDir instead of silently reading it.
// That refusal is only worth anything when commonDir is resolved INDEPENDENTLY
// of absPath: a caller that derives the base by walking up from the target makes
// the check vacuous, because the relative path is then correct by construction.
// settings.clonePreferencesRoot is the one caller, and it recovers the common
// dir by removing a compile-time constant suffix, which fails loudly on a path
// of the wrong shape rather than anchoring somewhere else.
//
// (The investigation stores used to be described here as callers. They are not:
// they hold a commonDir of their own and resolve run ids as names inside it,
// which is the stronger form — see investigate.StateStore.)
func OpenPathIn(commonDir, absPath string) (root *os.Root, name string, err error) {
	base, err := filepath.Abs(commonDir)
	if err != nil {
		return nil, "", fmt.Errorf("resolve %s: %w", commonDir, err)
	}
	target, err := filepath.Abs(absPath)
	if err != nil {
		return nil, "", fmt.Errorf("resolve %s: %w", absPath, err)
	}
	rel, err := filepath.Rel(base, target)
	if err != nil || rel == "." || paths.IsRelativeTraversal(rel) {
		return nil, "", fmt.Errorf("%q is not under %q", absPath, commonDir)
	}
	root, err = OpenAt(base)
	if err != nil {
		return nil, "", err
	}
	return root, filepath.ToSlash(rel), nil
}
// Package osroot provides traversal-resistant file I/O helpers built on os.Root
// (Go 1.24+). These helpers ensure that file operations cannot escape a scoped
// directory, preventing symlink attacks and TOCTOU races at the kernel level.
//
// These wrappers predate Go 1.25, which added native ReadFile/WriteFile/MkdirAll
// (etc.) on *os.Root; they remain as the codebase's stable, consistent helper
// surface and delegate to the native methods where those now exist.
//
// Errors from these functions are returned unwrapped so that callers can use
// os.IsNotExist() and errors.Is() directly without losing the original sentinel.
package osroot

import (
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strings"
	"sync"
)

// ReadFile reads the named file relative to root using os.Root for
// traversal-resistant access. The kernel enforces that the read cannot
// escape the root directory, preventing symlink and TOCTOU attacks.
func ReadFile(root *os.Root, name string) ([]byte, error) {
	f, err := root.Open(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer f.Close()

	data, err := io.ReadAll(f)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error
	}
	return data, nil
}

// ReadFileNoFollow reads name while refusing a symbolic link in any component.
// os.Root already prevents a link from escaping root, but follows links whose
// targets remain inside it. Entire-owned trees require the stronger property:
// every component must identify the object stored at that name.
func ReadFileNoFollow(root *os.Root, name string) ([]byte, error) {
	f, err := OpenNoFollow(root, name)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	data, err := io.ReadAll(f)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error
	}
	return data, nil
}

// OpenNoFollow opens an existing file without following any symlink component.
// Parent directories are opened and pinned one at a time; the leaf's second
// check closes its Lstat/Open race. Once verified, later replacements cannot
// redirect the open descriptor.
func OpenNoFollow(root *os.Root, name string) (*os.File, error) {
	parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
	if err != nil {
		return nil, err
	}
	defer closeParent()

	before, err := parent.Lstat(leaf)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if before.Mode()&os.ModeSymlink != 0 {
		return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
	}

	f, err := parent.Open(leaf)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if err := validateOpenedFile(parent, leaf, f); err != nil {
		_ = f.Close()
		return nil, err
	}
	return f, nil
}

// OpenFileNoFollow opens or creates a file without following any symlink.
// It is intended for append-style writers: O_TRUNC is rejected because
// truncating Entire-owned writes should use an atomic temp-file-and-rename
// operation instead. Unix builds add O_NOFOLLOW to close the write-before-
// validation race; other platforms still reject pre-existing links and verify
// the opened object before returning it.
func OpenFileNoFollow(root *os.Root, name string, flag int, perm os.FileMode) (*os.File, error) {
	if flag&os.O_TRUNC != 0 {
		return nil, errors.New("osroot: OpenFileNoFollow does not permit O_TRUNC")
	}
	parent, leaf, closeParent, err := OpenParentNoSymlinks(root, name)
	if err != nil {
		return nil, err
	}
	defer closeParent()

	if before, err := parent.Lstat(leaf); err == nil {
		if before.Mode()&os.ModeSymlink != 0 {
			return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
		}
	} else if !os.IsNotExist(err) {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}

	f, err := parent.OpenFile(leaf, flag|noFollowOpenFlag, perm)
	if err != nil {
		// Preserve the package sentinel when a link appeared after the first
		// Lstat and O_NOFOLLOW rejected it.
		if info, lstatErr := parent.Lstat(leaf); lstatErr == nil && info.Mode()&os.ModeSymlink != 0 {
			return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
		}
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if err := validateOpenedFile(parent, leaf, f); err != nil {
		_ = f.Close()
		return nil, err
	}
	return f, nil
}

func validateOpenedFile(root *os.Root, name string, f *os.File) error {
	pathInfo, err := root.Lstat(name)
	if err != nil {
		return err //nolint:wrapcheck // preserve original error classification
	}
	if pathInfo.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
	}
	openedInfo, err := f.Stat()
	if err != nil {
		return err //nolint:wrapcheck // preserve original error classification
	}
	if !os.SameFile(pathInfo, openedInfo) {
		return fmt.Errorf("%s changed while it was being opened", name)
	}
	return nil
}

// WriteFile writes data to the named file relative to root using os.Root
// for traversal-resistant access. Creates the file if it doesn't exist,
// truncates it if it does. The kernel enforces that the write cannot escape
// the root directory.
func WriteFile(root *os.Root, name string, data []byte, perm os.FileMode) (retErr error) {
	f, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, perm)
	if err != nil {
		return err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer func() {
		if closeErr := f.Close(); closeErr != nil && retErr == nil {
			retErr = closeErr
		}
	}()

	if _, err := f.Write(data); err != nil {
		return err //nolint:wrapcheck // preserve original error
	}
	return nil
}

// MkdirAll creates the directory named by name, along with any necessary
// parents, relative to root. The kernel enforces containment: a name that
// escapes root (absolute, or climbing above it via "..") is rejected. Already-
// existing directories are tolerated, like os.MkdirAll. This thin wrapper keeps
// the package's os.Root helper surface (alongside ReadFile/WriteFile/Remove)
// consistent at call sites.
func MkdirAll(root *os.Root, name string, perm os.FileMode) error {
	return root.MkdirAll(name, perm) //nolint:wrapcheck // preserve original error for errors.Is/os.IsNotExist
}

// Remove removes the named file relative to root using os.Root for
// traversal-resistant access. Returns nil if the file doesn't exist.
func Remove(root *os.Root, name string) error {
	err := root.Remove(name)
	if err != nil && !os.IsNotExist(err) {
		return err //nolint:wrapcheck // preserve original error
	}
	return nil
}

// ReadDir reads the named directory relative to root, returning its entries
// sorted by filename, like os.ReadDir. os.Root has no ReadDir method of its
// own, so this is the sanctioned way to list a directory without falling back
// to an unconfined os.ReadDir on a joined path.
func ReadDir(root *os.Root, name string) ([]os.DirEntry, error) {
	f, err := root.Open(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error for os.IsNotExist checks
	}
	defer f.Close()

	entries, err := f.ReadDir(-1)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error
	}
	slices.SortFunc(entries, func(a, b os.DirEntry) int {
		return strings.Compare(a.Name(), b.Name())
	})
	return entries, nil
}

// ReadDirNoSymlinks reads a directory after opening every component beneath
// root as a real directory. Unlike ReadDir, an in-root symlink is rejected
// rather than followed.
func ReadDirNoSymlinks(root *os.Root, name string) ([]os.DirEntry, error) {
	dir, closeDir, err := OpenDirNoSymlinks(root, name)
	if err != nil {
		return nil, err
	}
	defer closeDir()

	return ReadDir(dir, ".")
}

// ErrSymlinkedPath reports a symlink where a real path component was required.
// Callers match it with errors.Is.
var ErrSymlinkedPath = errors.New("path component is a symlink")

// MkdirAllNoSymlink is MkdirAll with one added refusal: if any component of
// name already exists as a symlink, it returns an error wrapping
// ErrSymlinkedPath instead of creating anything.
//
// os.Root alone is not enough here. It refuses to follow a symlink that escapes
// the root, but a symlink pointing elsewhere *inside* the root is followed
// silently, and an escaping one fails later with whatever errno the first open
// happens to hit — which surfaces to the user as an unexplained I/O failure far
// from the cause. Checking at the point the directory is established turns both
// into one named error while the caller still has the context to report it.
//
// Each component is opened relative to its already-pinned parent, including
// components created by this call. That makes creation and validation one
// descriptor-relative sequence rather than a check followed by MkdirAll.
func MkdirAllNoSymlink(root *os.Root, name string, perm os.FileMode) error {
	if name == "." {
		return nil
	}
	if !fs.ValidPath(name) {
		return fmt.Errorf("%q is not a valid root-relative path", name)
	}

	current := root
	var owned *os.Root
	defer func() {
		if owned != nil {
			_ = owned.Close()
		}
	}()
	for _, component := range strings.Split(name, "/") {
		if _, err := current.Lstat(component); os.IsNotExist(err) {
			if err := current.Mkdir(component, perm); err != nil && !errors.Is(err, fs.ErrExist) {
				return err //nolint:wrapcheck // preserve original error classification
			}
		} else if err != nil {
			return err //nolint:wrapcheck // preserve original error classification
		}
		next, err := OpenChild(current, component)
		if err != nil {
			return err
		}
		if owned != nil {
			_ = owned.Close()
		}
		owned = next
		current = next
	}
	return nil
}

// ErrWalkRootNotDirectory reports a walk root that exists but is not a
// directory. It is deliberately NOT ErrSymlinkedPath: "replace this link" and
// "this is a regular file" are different remedies, and conflating them is how a
// user gets told to fix the wrong thing.
var ErrWalkRootNotDirectory = errors.New("path is not a directory")

// OpenParentNoSymlinks opens and pins the parent directory of name while
// rejecting a symlink in every parent component. The returned close function
// must be called; it is a no-op when name is directly beneath root.
//
// Operations that must not follow parent symlinks should act on the returned
// root using leaf, rather than validating and then resolving name again from
// the original root. Holding the parent descriptor closes that check/use gap.
func OpenParentNoSymlinks(root *os.Root, name string) (parent *os.Root, leaf string, closeParent func(), err error) {
	if root == nil {
		return nil, "", nil, errors.New("osroot: root is required")
	}
	if !fs.ValidPath(name) || name == "." {
		return nil, "", nil, fmt.Errorf("%q is not a valid file name beneath root", name)
