	t.Logf("Cloning %s (full history, single branch) ...", hookPerfRepoURL)
	start := time.Now()

	testutil.RunGit(t, "", "clone", "--single-branch", hookPerfRepoURL, dir)
	t.Logf("Source clone completed in %s", time.Since(start).Round(time.Millisecond))

	return dir
}

