	t.Helper()

	dir := t.TempDir()
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		dir = resolved
	}

	testutil.RunGit(t, "", "clone", "--local", sourceDir, dir)

	return dir
}

